from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import numpy as np
import xarray as xr


def _load_case(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def _surface(case: dict[str, Any]) -> xr.DataArray:
    return xr.DataArray(
        np.asarray(case["values"], dtype=float),
        dims=("y", "x"),
        coords={
            "y": np.asarray(case["y"], dtype=float),
            "x": np.asarray(case["x"], dtype=float),
        },
        name="survey_surface",
        attrs={"crs": str(case["crs"])},
    )


def _remap_view(
    surface: xr.DataArray,
    case: dict[str, Any],
    view: dict[str, Any],
    method: str,
) -> np.ndarray:
    from xrspatial.reproject import reproject

    result = reproject(
        surface,
        target_crs=str(case["crs"]),
        bounds=tuple(float(v) for v in view["bounds"]),
        resolution=tuple(float(v) for v in view["resolution"]),
        resampling=method,
        nodata=float(case["nodata"]),
        transform_precision=0,
    )
    return np.asarray(result.values, dtype=float)


def _sample_values(values: np.ndarray, nodata: float) -> list[float | None]:
    flat = values.reshape(-1)
    if flat.size == 0:
        return []
    indexes = sorted({0, flat.size // 2, flat.size - 1})
    sample = []
    for index in indexes:
        value = float(flat[index])
        sample.append(None if np.isclose(value, nodata) else round(value, 6))
    return sample


def _summarize(values: np.ndarray, nodata: float) -> dict[str, Any]:
    nodata_mask = np.isclose(values, nodata)
    finite_mask = np.isfinite(values) & ~nodata_mask
    finite_values = values[finite_mask]
    summary: dict[str, Any] = {
        "shape": list(values.shape),
        "nodata_cells": int(np.count_nonzero(nodata_mask)),
        "finite_cells": int(np.count_nonzero(finite_mask)),
        "sample_values": _sample_values(values, nodata),
    }
    if finite_values.size:
        summary["finite_min"] = float(np.min(finite_values))
        summary["finite_max"] = float(np.max(finite_values))
        summary["finite_mean"] = float(np.mean(finite_values))
    else:
        summary["finite_min"] = None
        summary["finite_max"] = None
        summary["finite_mean"] = None
    return summary


def inspect_remap_observations(path: Path) -> dict[str, Any]:
    case = _load_case(path)
    surface = _surface(case)
    nodata = float(case["nodata"])

    view_reports = []
    for view in case["views"]:
        method_reports = []
        for method in view["methods"]:
            values = _remap_view(surface, case, view, method)
            method_reports.append(
                {
                    "method": method,
                    "summary": _summarize(values, nodata),
                }
            )
        view_reports.append(
            {
                "name": view["name"],
                "bounds": [float(v) for v in view["bounds"]],
                "methods": method_reports,
            }
        )

    return {
        "dataset": path.name,
        "source_shape": list(surface.shape),
        "crs": str(case["crs"]),
        "source_value_range": {
            "min": float(np.nanmin(surface.values)),
            "max": float(np.nanmax(surface.values)),
        },
        "views": view_reports,
        "finite_observation": bool(
            view_reports
            and all(
                method["summary"]["finite_cells"] > 0
                for view in view_reports
                for method in view["methods"]
            )
        ),
    }

"""Per-backend resampling via numba JIT (nearest/bilinear) or map_coordinates (cubic)."""
from __future__ import annotations

import math

import numpy as np
from numba import njit

try:
    from numba import cuda as _cuda
    _HAS_CUDA = True
except ImportError:
    _HAS_CUDA = False


_RESAMPLING_ORDERS = {
    'nearest': 0,
    'bilinear': 1,
    'cubic': 3,
}


def _validate_resampling(resampling):
    if resampling not in _RESAMPLING_ORDERS:
        raise ValueError(
            f"resampling must be one of {list(_RESAMPLING_ORDERS)}, "
            f"got {resampling!r}"
        )
    return _RESAMPLING_ORDERS[resampling]


# ---------------------------------------------------------------------------
# Numba kernels for nearest and bilinear resampling
# ---------------------------------------------------------------------------

@njit(nogil=True, cache=True)
def _resample_nearest_jit(src, row_coords, col_coords, nodata):
    """Nearest-neighbor resampling with NaN propagation."""
    h_out, w_out = row_coords.shape
    sh, sw = src.shape
    out = np.empty((h_out, w_out), dtype=np.float64)
    for i in range(h_out):
        for j in range(w_out):
            r = row_coords[i, j]
            c = col_coords[i, j]
            if r < -1.0 or r > sh or c < -1.0 or c > sw:
                out[i, j] = nodata
                continue
            ri = int(r + 0.5)
            ci = int(c + 0.5)
            if ri < 0:
                ri = 0
            if ri >= sh:
                ri = sh - 1
            if ci < 0:
                ci = 0
            if ci >= sw:
                ci = sw - 1
            v = src[ri, ci]
            # NaN check: works for float64
            if v != v:
                out[i, j] = nodata
            else:
                out[i, j] = v
    return out


@njit(nogil=True, cache=True)
def _resample_cubic_jit(src, row_coords, col_coords, nodata):
    """Catmull-Rom cubic resampling with NaN-aware fallback to bilinear.

    Separable: interpolate 4 row-slices along columns, then combine
    along rows.  When any of the 16 neighbors is NaN, falls back to
    bilinear with weight renormalization (matching GDAL behavior).
    """
    h_out, w_out = row_coords.shape
    sh, sw = src.shape
    out = np.empty((h_out, w_out), dtype=np.float64)
    for i in range(h_out):
        for j in range(w_out):
            r = row_coords[i, j]
            c = col_coords[i, j]
            if r < -1.0 or r > sh or c < -1.0 or c > sw:
                out[i, j] = nodata
                continue

            r0 = int(np.floor(r))
            c0 = int(np.floor(c))
            fr = r - r0
            fc = c - c0

            # Catmull-Rom column weights (a = -0.5)
            fc2 = fc * fc
            fc3 = fc2 * fc
            wc0 = -0.5 * fc3 + fc2 - 0.5 * fc
            wc1 = 1.5 * fc3 - 2.5 * fc2 + 1.0
            wc2 = -1.5 * fc3 + 2.0 * fc2 + 0.5 * fc
            wc3 = 0.5 * fc3 - 0.5 * fc2

            # Catmull-Rom row weights
            fr2 = fr * fr
            fr3 = fr2 * fr
            wr0 = -0.5 * fr3 + fr2 - 0.5 * fr
            wr1 = 1.5 * fr3 - 2.5 * fr2 + 1.0
            wr2 = -1.5 * fr3 + 2.0 * fr2 + 0.5 * fr
            wr3 = 0.5 * fr3 - 0.5 * fr2

            val = 0.0
            has_nan = False
            for di in range(4):
                ri = r0 - 1 + di
                ric = ri
                if ric < 0:
                    ric = 0
                elif ric >= sh:
                    ric = sh - 1
                # Interpolate along columns for this row
                rv = 0.0
                for dj in range(4):
                    cj = c0 - 1 + dj
                    cjc = cj
                    if cjc < 0:
                        cjc = 0
                    elif cjc >= sw:
                        cjc = sw - 1
                    sv = src[ric, cjc]
                    if sv != sv:  # NaN check
                        has_nan = True
                        break
                    if dj == 0:
                        rv = sv * wc0
                    elif dj == 1:
                        rv += sv * wc1
                    elif dj == 2:
                        rv += sv * wc2
                    else:
                        rv += sv * wc3
                if has_nan:
                    break
                if di == 0:
                    val = rv * wr0
                elif di == 1:
                    val += rv * wr1
                elif di == 2:
                    val += rv * wr2
                else:
                    val += rv * wr3

            if not has_nan:
                out[i, j] = val
            else:
                # Fall back to bilinear with weight renormalization
                r1 = r0 + 1
                c1 = c0 + 1
                dr = r - r0
                dc = c - c0

                w00 = (1.0 - dr) * (1.0 - dc)
                w01 = (1.0 - dr) * dc
                w10 = dr * (1.0 - dc)
                w11 = dr * dc

                accum = 0.0
                wsum = 0.0

                if 0 <= r0 < sh and 0 <= c0 < sw:
                    v = src[r0, c0]
                    if v == v:
                        accum += w00 * v
                        wsum += w00

                if 0 <= r0 < sh and 0 <= c1 < sw:
                    v = src[r0, c1]
                    if v == v:
                        accum += w01 * v
                        wsum += w01

                if 0 <= r1 < sh and 0 <= c0 < sw:
                    v = src[r1, c0]
                    if v == v:
                        accum += w10 * v
                        wsum += w10

                if 0 <= r1 < sh and 0 <= c1 < sw:
                    v = src[r1, c1]
                    if v == v:
                        accum += w11 * v
                        wsum += w11

                if wsum > 1e-10:
                    out[i, j] = accum / wsum
                else:
                    out[i, j] = nodata
    return out


@njit(nogil=True, cache=True)
def _resample_bilinear_jit(src, row_coords, col_coords, nodata):
    """Bilinear resampling matching GDAL's weight-renormalization approach.

    When a neighbor is out-of-bounds or NaN, its weight is excluded and
    the result is renormalized from the remaining valid neighbors.  This
    matches GDAL's GWKBilinearResample4Sample behavior.
    """
    h_out, w_out = row_coords.shape
    sh, sw = src.shape
    out = np.empty((h_out, w_out), dtype=np.float64)
    for i in range(h_out):
        for j in range(w_out):
            r = row_coords[i, j]
            c = col_coords[i, j]
            if r < -1.0 or r > sh or c < -1.0 or c > sw:
                out[i, j] = nodata
                continue

            r0 = int(np.floor(r))
            c0 = int(np.floor(c))
            r1 = r0 + 1
            c1 = c0 + 1
            dr = r - r0
            dc = c - c0

            w00 = (1.0 - dr) * (1.0 - dc)
            w01 = (1.0 - dr) * dc
            w10 = dr * (1.0 - dc)
            w11 = dr * dc

            accum = 0.0
            wsum = 0.0

            # Accumulate only valid, in-bounds neighbors
            if 0 <= r0 < sh and 0 <= c0 < sw:
                v = src[r0, c0]
                if v == v:  # not NaN
                    accum += w00 * v
                    wsum += w00

            if 0 <= r0 < sh and 0 <= c1 < sw:
                v = src[r0, c1]
                if v == v:
                    accum += w01 * v
                    wsum += w01

            if 0 <= r1 < sh and 0 <= c0 < sw:
                v = src[r1, c0]
                if v == v:
                    accum += w10 * v
                    wsum += w10

            if 0 <= r1 < sh and 0 <= c1 < sw:
                v = src[r1, c1]
                if v == v:
                    accum += w11 * v
                    wsum += w11

            if wsum > 1e-10:
                out[i, j] = accum / wsum
            else:
                out[i, j] = nodata
    return out


